#include <iostream>

int main() {
    int cantidad = 8;
    const auto antes = sizeof(cantidad);

    cantidad = 600;

    std::cout << cantidad << ":"
              << (antes == sizeof(cantidad)) << ":"
              << (sizeof(cantidad) == sizeof(int));
    return 0;
}

